import os
import json
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _norm_value(value: Any) -> Any:
    if value is None:
        return None
    for attr in ("content", "value_string", "value_date", "value_currency", "value_number"):
        if hasattr(value, attr):
            v = getattr(value, attr)
            if v is not None:
                return str(v)
    return str(value)


def _norm_date(value: Any) -> Optional[str]:
    if value is None:
        return None
    if hasattr(value, "value_date") and value.value_date is not None:
        return str(value.value_date)
    if hasattr(value, "content") and value.content:
        return str(value.content)
    return str(value)


def _norm_money(value: Any) -> Optional[float]:
    if value is None:
        return None
    if hasattr(value, "amount") and value.amount is not None:
        try:
            return float(value.amount)
        except Exception:
            pass
    if hasattr(value, "content") and value.content:
        txt = str(value.content).strip()
        try:
            return float("".join(ch for ch in txt if ch in "0123456789.-"))
        except Exception:
            return txt
    try:
        return float(value)
    except Exception:
        return None


def _extract_line_items(result: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    documents = getattr(result, "documents", None) or []
    for doc in documents:
        fields = getattr(doc, "fields", {}) or {}
        line_items_field = fields.get("Items") or fields.get("LineItems")
        if not line_items_field:
            continue

        for item in getattr(line_items_field, "value_array", []) or []:
            item_fields = getattr(item, "value_object", None)
            if item_fields is None:
                continue

            def gf(*names):
                for n in names:
                    if n in item_fields and item_fields[n] is not None:
                        return item_fields[n]
                return None

            desc = gf("Description", "ProductCode", "Name")
            qty = gf("Quantity")
            unit = gf("UnitPrice", "Unit Cost", "UnitPrice")
            amount = gf("Amount", "TotalPrice", "NetPrice")

            items.append(
                {
                    "description": _norm_value(desc),
                    "quantity": _norm_value(qty),
                    "unit_price": _norm_money(unit),
                    "amount": _norm_money(amount),
                }
            )

    if items:
        return items

    for page in getattr(result, "pages", []) or []:
        for table in getattr(page, "tables", []) or []:
            cells = getattr(table, "cells", []) or []
            if not cells:
                continue
    return items


def extract_invoice_fields(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        analyze_request=document_bytes,
        content_type=content_type,
    )
    result = poller.result()

    vendor = None
    invoice_date = None
    total = None

    documents = getattr(result, "documents", None) or []
    if documents:
        doc = documents[0]
        fields = getattr(doc, "fields", {}) or {}

        def get_field(*names):
            for name in names:
                if name in fields and fields[name] is not None:
                    return fields[name]
            return None

        vendor_field = get_field("VendorName", "MerchantName", "Vendor")
        date_field = get_field("InvoiceDate", "Date")
        total_field = get_field("InvoiceTotal", "Total")

        vendor = _norm_value(vendor_field)
        invoice_date = _norm_date(date_field)
        total = _norm_money(total_field)

    line_items = _extract_line_items(result)

    return {
        "vendor": vendor,
        "date": invoice_date,
        "total": total,
        "line_items": line_items,
    }


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <invoice_file_path>")

    path = sys.argv[1]
    with open(path, "rb") as f:
        data = f.read()

    output = extract_invoice_fields(data, content_type="application/pdf")
    print(json.dumps(output, indent=2, ensure_ascii=False))
